"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  ShieldWarningIcon as PhShield,
  MegaphoneSimpleIcon as PhMegaphone,
  AtIcon as PhAt,
  CheckIcon as PhCheck,
  ArrowClockwiseIcon as PhReset,
} from "@phosphor-icons/react";

interface Channel {
  id: string;
  label: string;
  detail: string;
  icon: typeof PhShield;
}

const CHANNELS: Channel[] = [
  { id: "security", label: "Security alert", detail: "New sign-in from an unrecognized device.", icon: PhShield },
  { id: "product", label: "Product update", detail: "Dark mode is now available in Settings.", icon: PhMegaphone },
  { id: "mention", label: "You were mentioned", detail: "@Alex mentioned you in #design-review.", icon: PhAt },
];

const MAX_STREAK = 3;

function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={12} aria-hidden />;
}

function intensityOf(streak: number) {
  return Math.min(1, streak / MAX_STREAK);
}

function AttentionIcon({
  Icon,
  intensity,
  pulseDuration,
  celebrate,
  shouldReduceMotion,
}: {
  Icon: typeof PhShield;
  intensity: number;
  pulseDuration: number;
  celebrate: boolean;
  shouldReduceMotion: boolean | null;
}) {
  return (
    <span className="relative flex h-8 w-8 shrink-0 items-center justify-center">
      <motion.span
        aria-hidden
        className={`absolute inset-0 rounded-full ${intensity > 0.5 ? "bg-rose-500/25" : "bg-amber-500/20"}`}
        animate={shouldReduceMotion || intensity === 0 ? { opacity: 0, scale: 1 } : { opacity: [0.6, 0, 0.6], scale: [1, 1.5, 1] }}
        transition={{ duration: pulseDuration || 2.2, repeat: Infinity, ease: "easeInOut" }}
      />
      {celebrate && !shouldReduceMotion && (
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full border-2 border-emerald-400/60"
          initial={{ scale: 0.8, opacity: 0.9 }}
          animate={{ scale: 1.8, opacity: 0 }}
          transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
        />
      )}
      <motion.span
        animate={celebrate && !shouldReduceMotion ? { scale: [1, 1.15, 1] } : { scale: 1 }}
        transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
        className={`relative flex h-8 w-8 shrink-0 items-center justify-center rounded-full transition-colors duration-300 ${
          intensity > 0.5
            ? "bg-rose-500/15 text-rose-600 dark:text-rose-400"
            : intensity > 0
              ? "bg-amber-500/15 text-amber-600 dark:text-amber-400"
              : "bg-slate-100 text-slate-500 dark:bg-white/10 dark:text-slate-400"
        }`}
      >
        <Icon size={15} aria-hidden />
      </motion.span>
    </span>
  );
}

function ChannelBody({
  channel,
  streak,
  intensity,
  acknowledged,
  onOpen,
  onSnooze,
  shouldReduceMotion,
}: {
  channel: Channel;
  streak: number;
  intensity: number;
  acknowledged: boolean;
  onOpen: () => void;
  onSnooze: () => void;
  shouldReduceMotion: boolean | null;
}) {
  return (
    <div className="min-w-0 flex-1">
      <p className="text-sm font-medium text-slate-800 dark:text-slate-100">{channel.label}</p>
      <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">{channel.detail}</p>
      <p
        className={`mt-1 text-[11px] font-medium ${
          intensity > 0.5 ? "text-rose-600 dark:text-rose-400" : intensity > 0 ? "text-amber-600 dark:text-amber-400" : "text-slate-400 dark:text-slate-500"
        }`}
      >
        {streak === 0 ? "Just opened, back to calm." : `Ignored ${streak} time${streak === 1 ? "" : "s"} in a row.`}
      </p>

      <div className="mt-2 flex items-center gap-2">
        <motion.button
          type="button"
          onClick={onOpen}
          whileHover={shouldReduceMotion ? undefined : { y: -1 }}
          whileTap={shouldReduceMotion ? undefined : { scale: 0.96 }}
          className="inline-flex items-center gap-1 rounded-lg bg-slate-900 px-2.5 py-1 text-xs font-medium text-white transition-colors hover:bg-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
        >
          <AnimatePresence mode="wait" initial={false}>
            {acknowledged ? (
              <motion.span key="done" initial={{ opacity: 0, scale: 0.6 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.6 }} className="flex items-center gap-1">
                <CheckIcon />
                Opened
              </motion.span>
            ) : (
              <motion.span key="open" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                Open
              </motion.span>
            )}
          </AnimatePresence>
        </motion.button>
        <motion.button
          type="button"
          onClick={onSnooze}
          whileHover={shouldReduceMotion ? undefined : { y: -1 }}
          whileTap={shouldReduceMotion ? undefined : { scale: 0.96 }}
          className="rounded-lg px-2.5 py-1 text-xs font-medium text-slate-500 transition-colors hover:bg-black/5 dark:text-slate-400 dark:hover:bg-white/10"
        >
          Not now
        </motion.button>
      </div>
    </div>
  );
}

interface AttentionGradientProps {
  className?: string;
}

export function AttentionGradient({ className }: AttentionGradientProps) {
  const [streaks, setStreaks] = useState<Record<string, number>>(() => Object.fromEntries(CHANNELS.map((c) => [c.id, 0])));
  const [acknowledged, setAcknowledged] = useState<string | null>(null);
  const [celebrateId, setCelebrateId] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const open = (id: string) => {
    setStreaks((prev) => ({ ...prev, [id]: 0 }));
    setAcknowledged(id);
    setCelebrateId(id);
    setTimeout(() => setAcknowledged((a) => (a === id ? null : a)), 700);
    setTimeout(() => setCelebrateId((c) => (c === id ? null : c)), 650);
  };

  const snooze = (id: string) => {
    setStreaks((prev) => ({ ...prev, [id]: Math.min(MAX_STREAK, prev[id] + 1) }));
  };

  const reset = () => {
    setStreaks(Object.fromEntries(CHANNELS.map((c) => [c.id, 0])));
    setAcknowledged(null);
    setCelebrateId(null);
  };

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <h3 className="text-sm font-semibold text-slate-900 dark:text-white">Notifications</h3>
          <motion.button
            type="button"
            onClick={reset}
            aria-label="Reset all channels"
            whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ResetIcon />
          </motion.button>
        </div>

        <div className="mt-3 space-y-2.5">
          {CHANNELS.map((channel) => {
            const streak = streaks[channel.id];
            const intensity = intensityOf(streak);
            const Icon = channel.icon;
            const pulseDuration = shouldReduceMotion ? 0 : 2.2 - intensity * 1.5;
            return (
              <div key={channel.id} className="relative overflow-hidden rounded-xl border border-slate-200/70 dark:border-white/10">
                <span className="absolute inset-0 bg-slate-50 dark:bg-white/[0.03]" aria-hidden />
                <motion.span
                  className="absolute inset-0 bg-amber-500/10 dark:bg-amber-500/[0.08]"
                  aria-hidden
                  animate={{ opacity: Math.min(1, intensity * 2) }}
                  transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                />
                <motion.span
                  className="absolute inset-0 bg-rose-500/10 dark:bg-rose-500/[0.08]"
                  aria-hidden
                  animate={{ opacity: Math.max(0, intensity * 2 - 1) }}
                  transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                />

                {streak > 0 ? (
                  <motion.div
                    key={streak}
                    initial={{ x: 0 }}
                    animate={shouldReduceMotion ? { x: 0 } : { x: [0, -3, 3, -2, 2, 0] }}
                    transition={{ duration: 0.4, ease: [0.36, 0.07, 0.19, 0.97] }}
                    className="relative flex items-start gap-3 p-3"
                  >
                    <AttentionIcon Icon={Icon} intensity={intensity} pulseDuration={pulseDuration} celebrate={celebrateId === channel.id} shouldReduceMotion={shouldReduceMotion} />
                    <ChannelBody
                      channel={channel}
                      streak={streak}
                      intensity={intensity}
                      acknowledged={acknowledged === channel.id}
                      onOpen={() => open(channel.id)}
                      onSnooze={() => snooze(channel.id)}
                      shouldReduceMotion={shouldReduceMotion}
                    />
                  </motion.div>
                ) : (
                  <div className="relative flex items-start gap-3 p-3">
                    <AttentionIcon Icon={Icon} intensity={intensity} pulseDuration={pulseDuration} celebrate={celebrateId === channel.id} shouldReduceMotion={shouldReduceMotion} />
                    <ChannelBody
                      channel={channel}
                      streak={streak}
                      intensity={intensity}
                      acknowledged={acknowledged === channel.id}
                      onOpen={() => open(channel.id)}
                      onSnooze={() => snooze(channel.id)}
                      shouldReduceMotion={shouldReduceMotion}
                    />
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Urgency isn&apos;t a fixed badge, it&apos;s computed from what you actually do: ignore a channel a few times and it genuinely escalates, open it once and it snaps right back to calm.
      </p>
    </div>
  );
}
